HASHES={'AteTests/WidgetsIntentsTests.swift': '174811f2d9df7a25e1aece858e62fe2012c3b66a8dce132d57cb9f3e4373e6cb', 'AteUITests/CoverageUITests.swift': '79311d1b07405e467c9f8fce5fd1bbb5350b231621a35faed281aa705c23da19', '.github/workflows/compile-check.yml': '92821ae0ace5092c880100b5e3abcbc41062d86dadda2696730650d84961109b'}
def restore_relay_return_capture(test,source,file):
    for new,old in reversed(CHANGES[file]):
        test.assertEqual(source.count(new),1)
        source=source.replace(new,old,1)
    return source
class RelayReturnCaptureTests(unittest.TestCase):
    def test_every_original_file_reconstructs(self):
        for file in CHANGES:
            self.assertEqual(hashlib.sha256(restore_relay_return_capture(self,normalize('source:'+file,(ROOT/file).read_text()),file).encode()).hexdigest(),HASHES[file])
